def keep_existing_approvals_published(apps, schema_editor):
    """Uploads approved before verify/publish were split were already in forecasting history:
    record them as published (by their reviewer, at their review time) so nothing drops out."""
    DatasetUpload = apps.get_model("schools", "DatasetUpload")
    DemandRecord = apps.get_model("schools", "DemandRecord")
    for upload in DatasetUpload.objects.filter(review_status="approved", processing_status="processed",
                                               published_at__isnull=True):
        when = upload.reviewed_at or upload.uploaded_at
        upload.published_at, upload.published_by_id = when, upload.reviewed_by_id
        upload.save(update_fields=["published_at", "published_by"])
        DemandRecord.objects.filter(upload=upload, status="approved").update(published_at=when)


